{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "description": "Green roofs per neighborhood, from intersects: the 15 neighborhoods with the most.",
  "width": 320,
  "height": {
    "step": 14
  },
  "transform": [
    {
      "aggregate": [
        {
          "op": "count",
          "as": "roofs"
        }
      ],
      "groupby": [
        "pri_neigh"
      ]
    },
    {
      "window": [
        {
          "op": "row_number",
          "as": "rank"
        }
      ],
      "sort": [
        {
          "field": "roofs",
          "order": "descending"
        },
        {
          "field": "pri_neigh",
          "order": "ascending"
        }
      ]
    },
    {
      "filter": "datum.rank <= 15"
    }
  ],
  "mark": "bar",
  "encoding": {
    "y": {
      "field": "pri_neigh",
      "type": "nominal",
      "sort": "-x",
      "title": null
    },
    "x": {
      "field": "roofs",
      "type": "quantitative",
      "title": "green roofs"
    },
    "tooltip": [
      {
        "field": "pri_neigh",
        "title": "neighborhood"
      },
      {
        "field": "roofs",
        "title": "green roofs"
      }
    ]
  }
}

{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "description": "Sidewalk labels within each neighborhood, from the counts output.",
  "width": 320,
  "height": 380,
  "projection": {
    "type": "mercator"
  },
  "mark": {
    "type": "geoshape",
    "stroke": "white",
    "strokeWidth": 0.5
  },
  "encoding": {
    "color": {
      "field": "point_count",
      "type": "quantitative",
      "title": "sidewalk labels",
      "scale": {
        "scheme": "blues"
      }
    },
    "tooltip": [
      {
        "field": "pri_neigh",
        "title": "neighborhood"
      },
      {
        "field": "point_count",
        "title": "sidewalk labels"
      }
    ]
  }
}

{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "description": "Sidewalk labels per neighborhood by type, from contains: the 12 neighborhoods with the most.",
  "width": 320,
  "height": {
    "step": 14
  },
  "transform": [
    {
      "joinaggregate": [
        {
          "op": "count",
          "as": "labels"
        }
      ],
      "groupby": [
        "pri_neigh"
      ]
    },
    {
      "window": [
        {
          "op": "dense_rank",
          "as": "rank"
        }
      ],
      "sort": [
        {
          "field": "labels",
          "order": "descending"
        }
      ]
    },
    {
      "filter": "datum.rank <= 12"
    }
  ],
  "mark": "bar",
  "encoding": {
    "y": {
      "field": "pri_neigh",
      "type": "nominal",
      "title": null,
      "sort": {
        "field": "labels",
        "op": "max",
        "order": "descending"
      }
    },
    "x": {
      "aggregate": "count",
      "type": "quantitative",
      "title": "sidewalk labels"
    },
    "color": {
      "field": "label_type",
      "type": "nominal",
      "title": "label type"
    }
  }
}

